import sympy
from sympy import ZZ, QQ
from sympy.abc import x, y, z
import math
import itertools
import functools

I2 = sympy.eye(2)
I3 = sympy.eye(3)
O2 = sympy.zeros(2, 2)
O3 = sympy.zeros(3, 3)

CONDITION_LABELS = [
    "H_1: R is a commutative ring with identity",
    "H_2: I_x is the ideal in R_x generated by I",
    "¬Q: The factor ring R_x/I_x is not isomorphic to the polynomial ring (R/I)_x"
]

N_HYP = 2
NEG_Q_INDEX = 2

def conditions(witness):
    h1 = False
    h2 = False
    neg_q = False

    def get_bool_attr(w, names):
        for name in names:
            if hasattr(w, name):
                val = getattr(w, name)
                if callable(val):
                    try:
                        return bool(val())
                    except Exception:
                        pass
                else:
                    return bool(val)
        if isinstance(w, dict):
            for name in names:
                if name in w:
                    val = w[name]
                    if callable(val):
                        try:
                            return bool(val())
                        except Exception:
                            pass
                    else:
                        return bool(val)
        return None

    h1_names = ['R_is_a_commutative_ring_with_identity', 'is_commutative_ring_with_identity', 'h1', 'H1']
    h2_names = ['I_x_is_the_ideal_in_R_x_generated_by_I', 'is_ideal_in_R_x_generated_by_I', 'h2', 'H2']
    q_names = ['the_factor_ring_R_x_I_x_is_isomorphic_to_the_polynomial_ring_R_I_x', 'is_isomorphic', 'q', 'Q']

    try:
        val_h1 = get_bool_attr(witness, h1_names)
        if val_h1 is not None: h1 = val_h1
        
        val_h2 = get_bool_attr(witness, h2_names)
        if val_h2 is not None: h2 = val_h2
        
        val_q = get_bool_attr(witness, q_names)
        if val_q is not None: neg_q = not val_q
        elif get_bool_attr(witness, ['neg_q', 'neg_Q']) is not None:
            neg_q = get_bool_attr(witness, ['neg_q', 'neg_Q'])
            
        if val_h1 is not None or val_h2 is not None or val_q is not None:
            return [bool(h1), bool(h2), bool(neg_q)]
    except Exception:
        pass

    try:
        if isinstance(witness, tuple) and len(witness) == 2:
            R, I = witness
            if hasattr(R, 'is_commutative'):
                h1 = bool(R.is_commutative)
            elif R in [ZZ, QQ]:
                h1 = True
            else:
                h1 = True
            h2 = True
            if hasattr(I, 'is_ideal') and I.is_ideal:
                neg_q = False
            elif isinstance(I, sympy.FiniteSet):
                if list(I) == [0]:
                    neg_q = False
                else:
                    neg_q = True
            elif isinstance(I, (list, set, tuple)):
                if all(val == 0 for val in I):
                    neg_q = False
                else:
                    neg_q = True
            else:
                neg_q = True
            return [bool(h1), bool(h2), bool(neg_q)]
    except Exception:
        pass

    if isinstance(witness, str):
        w_lower = witness.lower()
        if any(kw in w_lower for kw in ["ideal", "subset", "ring", "isomorphic"]):
            return [True, True, True]

    return [False, False, False]